import unittest
from candidate import common

class TestCommon(unittest.TestCase):
    def test_common_basic_example_1(self):
        self.assertEqual(common([1, 4, 3, 34, 653, 2, 5], [5, 7, 1, 5, 9, 653, 121]), [1, 5, 653])

    def test_common_basic_example_2(self):
        self.assertEqual(common([5, 3, 2, 8], [3, 2]), [2, 3])

    def test_common_empty_both_lists(self):
        self.assertEqual(common([], []), [])

    def test_common_first_list_empty(self):
        self.assertEqual(common([], [1, 2, 3]), [])

    def test_common_second_list_empty(self):
        self.assertEqual(common([1, 2, 3], []), [])

    def test_common_no_overlap(self):
        self.assertEqual(common([1, 2, 3], [4, 5, 6]), [])

    def test_common_duplicates_in_lists(self):
        self.assertEqual(common([1, 1, 2, 2], [2, 2, 3, 3]), [2])

    def test_common_single_common_element(self):
        self.assertEqual(common([5], [5]), [5])

    def test_common_none_first_argument(self):
        with self.assertRaises(TypeError):
            common(None, [1, 2, 3])

    def test_common_none_second_argument(self):
        with self.assertRaises(TypeError):
            common([1, 2, 3], None)

    def test_common_type_error_non_iterable_first(self):
        with self.assertRaises(TypeError):
            common(42, [1, 2, 3])
